import {Button, LinkButton} from '@primer/react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useCreateCSV} from '@github-ui/licensing-common/hooks/useCreateCSV'
import {DownloadIcon} from '@primer/octicons-react'
import {useNavigate} from '@github-ui/use-navigate'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'

export interface Props {
  isCopilotEnabled: boolean
  copilotCanBeReenabled: boolean
  businessSlug: string
  isStafftools: boolean
  isDfdTrial: boolean
  isAuthenticatedThroughDfd: boolean
  onCsvDownload: (arg0: string) => void
  onEnablementError: (arg0: boolean, arg1: string) => void
}

export function SummaryHeaderButtons({
  isCopilotEnabled,
  copilotCanBeReenabled,
  businessSlug,
  isStafftools,
  isAuthenticatedThroughDfd,
  isDfdTrial,
  onCsvDownload,
  onEnablementError,
}: Props) {
  const navigate = useNavigate()
  const {basePath} = useNavigation()
  const manageUrl = `${basePath}/licensing/copilot`
  const method = isStafftools ? 'POST' : 'GET'
  const csvActivityDownloadUrl = isStafftools
    ? `${basePath}/copilot_generate_activity_csv`
    : `${basePath}/settings/download_seat_management_activity`
  const enablementUrl = `${basePath}/settings/update_copilot_enablement`
  const trialActivationsUrl = `${basePath}/trial_activations`

  const {loading: activityLoading, makeCSVRequest: activityDownload} = useCreateCSV({
    slug: businessSlug,
    endpoint: csvActivityDownloadUrl,
    async: true,
    method,
    onSuccess: () => onCsvDownload('success'),
  })

  const handleSubmit = async () => {
    const data = new FormData()
    const enablementValue = isDfdTrial ? 'all_organizations' : 'selected_organizations'
    data.append('copilot_enabled', enablementValue)
    // improve error handling here.
    const response = await verifiedFetch(enablementUrl, {
      method: 'PUT',
      body: data,
    })
    if (response.ok) {
      navigate(manageUrl)
    } else {
      let errorMessage = 'An error occurred while enabling Copilot for your enterprise account.'

      if (response.status === 422) {
        try {
          const errorData = await response.json()
          if (errorData.error_type === 'no_organizations') {
            errorMessage = 'To enable Copilot, you need to create an organization first.'
          }
        } catch {
          // If error reading data, we can just use the default message.
        }
      }

      onEnablementError(true, errorMessage)
    }
  }

  return (
    <>
      {isCopilotEnabled || copilotCanBeReenabled ? (
        <>
          <Button
            leadingVisual={DownloadIcon}
            onClick={activityDownload}
            loading={activityLoading}
            disabled={activityLoading}
            data-testid="download-csv-button"
          >
            Get activity report
          </Button>
          {!isStafftools && (
            <>
              {isCopilotEnabled && (
                <LinkButton variant="default" href={manageUrl} data-testid="manage-copilot-button">
                  Manage
                </LinkButton>
              )}
              {copilotCanBeReenabled && (
                <Button variant="primary" onClick={handleSubmit} data-testid="reenable-copilot-button">
                  Re-enable Copilot
                </Button>
              )}
            </>
          )}
        </>
      ) : (
        !isStafftools &&
        (isDfdTrial && !isAuthenticatedThroughDfd ? (
          <LinkButton variant="primary" href={trialActivationsUrl} data-testid="validate-payment-enable-copilot-button">
            Validate payment and enable Copilot
          </LinkButton>
        ) : (
          <Button variant="primary" onClick={handleSubmit} data-testid="enable-copilot-button">
            Enable Copilot
          </Button>
        ))
      )}
    </>
  )
}

try{ SummaryHeaderButtons.displayName ||= 'SummaryHeaderButtons' } catch {}